// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.misc;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;

import org.assertj.core.api.ThrowableAssert.ThrowingCallable;
import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code miscf:nullIf(a, b)}: SPARQL {@code =} semantics for the comparison, the first argument returned
 * untouched otherwise.
 */
class NullIfEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private final NullIf nullIf = new NullIf();

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static Literal decimal(String v) {
		return VF.createLiteral(v, CoreDatatype.XSD.DECIMAL);
	}

	private static Literal str(String v) {
		return VF.createLiteral(v);
	}

	private static void assertError(ThrowingCallable callable) {
		assertThatThrownBy(callable).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void equalArgumentsAreAnError() {
		assertError(() -> nullIf.evaluate(VF, integer(1), integer(1)));
		assertError(() -> nullIf.evaluate(VF, str("a"), str("a")));
		assertError(() -> nullIf.evaluate(VF, VF.createLiteral("a", "en"), VF.createLiteral("a", "en")));
		assertError(() -> nullIf.evaluate(VF, VF.createLiteral(true), VF.createLiteral(true)));
		assertError(() -> nullIf.evaluate(VF, VF.createLiteral(2.5), VF.createLiteral(2.5)));
		assertError(() -> nullIf.evaluate(VF, str("a"), VF.createLiteral("a", CoreDatatype.XSD.STRING)));
	}

	@Test
	void unequalArgumentsReturnTheFirstUnchanged() {
		Literal decimal = decimal("1.50");
		Value result = nullIf.evaluate(VF, decimal, integer(2));
		assertThat(result).isSameAs(decimal);
		assertThat(((Literal) result).getLabel()).isEqualTo("1.50");
		assertThat(((Literal) result).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		Literal tagged = VF.createLiteral("a", "en");
		assertThat(nullIf.evaluate(VF, tagged, str("b"))).isSameAs(tagged);
		assertThat(((Literal) nullIf.evaluate(VF, tagged, str("b"))).getLanguage()).contains("en");
		Literal custom = VF.createLiteral("x", VF.createIRI("urn:datatype"));
		assertThat(nullIf.evaluate(VF, custom, str("y"))).isSameAs(custom);
		assertThat(nullIf.evaluate(VF, integer(1), VF.createLiteral(1.5))).isEqualTo(integer(1));
	}

	@Test
	void numericEqualityIgnoresTheDatatype() {
		// 1 = 1.0 under SPARQL numeric comparison, so the result is unbound
		assertError(() -> nullIf.evaluate(VF, integer(1), decimal("1.0")));
		assertError(() -> nullIf.evaluate(VF, integer(1), VF.createLiteral("1", CoreDatatype.XSD.LONG)));
		assertError(() -> nullIf.evaluate(VF, VF.createLiteral(1.0), VF.createLiteral("1", CoreDatatype.XSD.FLOAT)));
		assertError(() -> nullIf.evaluate(VF, decimal("0.10"), decimal("0.1")));
		assertThat(nullIf.evaluate(VF, integer(1), decimal("1.01"))).isEqualTo(integer(1));
	}

	@Test
	void stringVersusNumberIsTreatedAsNotEqual() {
		// pins current behaviour: SPARQL "=" raises a type error for "1" vs 1; nullIf falls back to RDF term equality
		// and therefore returns the first argument instead of propagating the error
		assertThat(nullIf.evaluate(VF, str("1"), integer(1))).isEqualTo(str("1"));
		assertThat(nullIf.evaluate(VF, integer(1), str("1"))).isEqualTo(integer(1));
		assertThat(nullIf.evaluate(VF, VF.createLiteral(true), integer(1))).isEqualTo(VF.createLiteral(true));
		assertThat(nullIf.evaluate(VF, VF.createLiteral("x", VF.createIRI("urn:dt1")),
				VF.createLiteral("x", VF.createIRI("urn:dt2"))))
						.isEqualTo(VF.createLiteral("x", VF.createIRI("urn:dt1")));
	}

	@Test
	void irisAndBlankNodes() {
		IRI a = VF.createIRI("urn:a");
		IRI b = VF.createIRI("urn:b");
		assertError(() -> nullIf.evaluate(VF, a, VF.createIRI("urn:a")));
		assertThat(nullIf.evaluate(VF, a, b)).isSameAs(a);
		BNode x = VF.createBNode("x");
		assertError(() -> nullIf.evaluate(VF, x, VF.createBNode("x")));
		assertThat(nullIf.evaluate(VF, x, VF.createBNode("y"))).isSameAs(x);
		assertThat(nullIf.evaluate(VF, a, str("urn:a"))).isSameAs(a);
		assertThat(nullIf.evaluate(VF, str("urn:a"), a)).isEqualTo(str("urn:a"));
		assertThat(nullIf.evaluate(VF, x, a)).isSameAs(x);
	}

	@Test
	void languageTaggedVersusPlain() {
		Literal tagged = VF.createLiteral("a", "en");
		assertThat(nullIf.evaluate(VF, tagged, str("a"))).isSameAs(tagged);
		assertThat(nullIf.evaluate(VF, str("a"), tagged)).isEqualTo(str("a"));
		assertThat(nullIf.evaluate(VF, tagged, VF.createLiteral("a", "fr"))).isSameAs(tagged);
		assertThat(nullIf.evaluate(VF, tagged, VF.createLiteral("b", "en"))).isSameAs(tagged);
	}

	@Test
	void tripleTerms() {
		Value triple = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), integer(1));
		Value sameValue = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), decimal("1.0"));
		Value other = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), integer(2));
		assertError(() -> nullIf.evaluate(VF, triple,
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), integer(1))));
		// component-wise SPARQL "=": 1 equals 1.0
		assertError(() -> nullIf.evaluate(VF, triple, sameValue));
		assertThat(nullIf.evaluate(VF, triple, other)).isSameAs(triple);
		assertThat(nullIf.evaluate(VF, triple, integer(1))).isSameAs(triple);
	}

	@Test
	void unboundArgumentIsAnError() {
		assertError(() -> nullIf.evaluate(VF, null, integer(1)));
		assertError(() -> nullIf.evaluate(VF, integer(1), null));
		assertError(() -> nullIf.evaluate(VF, null, null));
	}

	@Test
	void wrongArityIsAnError() {
		assertError(() -> nullIf.evaluate(VF));
		assertError(() -> nullIf.evaluate(VF, integer(1)));
		assertError(() -> nullIf.evaluate(VF, integer(1), integer(2), integer(3)));
	}
}
